function journals(title="Journal Entries"){const a=state.journals.filter(x=>x.companyId===companyId());const vouchers=title==="Vouchers";const rejected=state.rejectedSources||[];const discovered=vouchers?discoverSources(state,companyId(),branchId()):[];const rejectedList=discovered.filter(x=>rejected.some(r=>r.key===x.key)).map(x=>({...x,reason:rejected.find(r=>r.key===x.key)?.reason}));const reviewModule=sessionStorage.getItem("finance-review-module")||"All";const modules=["All",...new Set(discovered.map(x=>x.module))];const toReview=discovered.filter(x=>!rejected.some(r=>r.key===x.key)).filter(x=>reviewModule==="All"||x.module===reviewModule);return head(title,"Draft, posted, reversal and source-linked journals.",`<button class="btn primary" data-action="journal">New voucher</button>${vouchers?' <button class="btn secondary" data-action="pos-settlement">Settle POS Clearing</button>':""}`)+(vouchers?`<section class="panel export-panel"><div class="panel-head"><h2>Source Transactions to Review</h2><strong>${toReview.length} record(s)</strong></div>${modules.length>1?`<div class="padded"><label>Filter by module<select class="input" id="review-module-filter">${modules.map(m=>`<option value="${esc(m)}" ${m===reviewModule?"selected":""}>${esc(m)}</option>`).join("")}</select></label></div>`:""}${toReview.length?sourceTable(toReview):empty("Nothing to review","All discovered Sales/Purchases/Banking source events are posted, returned for correction, or no connected data exists.")}</section>${rejectedList.length?`<section class="panel export-panel"><div class="panel-head"><h2>Rejected / Returned for correction</h2><strong>${rejectedList.length} record(s)</strong></div>${table(["Date","Source","No.","Reason","Action"],rejectedList.map(x=>`<tr><td>${x.date}</td><td>${esc(x.module)} · ${esc(x.entityType)}</td><td class="mono">${esc(x.documentNumber)}</td><td>${esc(x.reason||"")}</td><td><button class="text-button" data-restore-source="${esc(x.key)}">Return to review</button></td></tr>`))}</section>`:""}`:"")+`<section class="panel export-panel"><div class="panel-head"><h2>${vouchers?"Draft / Posted Vouchers":"Journal register"}</h2></div>${journalTable(a)}</section>`}
function gl(){const aid=sessionStorage.getItem("finance-ledger-account")||state.accounts.find(x=>x.companyId===companyId())?.id,a=state.accounts.find(x=>x.id===aid),r=aid?ledger(state,{companyId:companyId(),accountId:aid,start:filters.start,end:filters.end}):[];return head("General Ledger","Running balance from immutable Posted journals.",`<button class="btn secondary" data-export="ledger">Export Excel</button>`)+`<section class="panel padded"><label>Account<select class="input" id="ledger-account">${accounts("",aid)}</select></label></section><section class="panel export-panel"><div class="panel-head"><h2>${esc(a?.name||"Select account")}</h2></div>${r.length?table(["Date","Voucher","Source","Narration","Debit","Credit","Running Balance"],r.map(x=>`<tr><td>${x.date}</td><td class="mono">${x.journalNumber}</td><td>${esc(x.sourceDocument||"—")}</td><td>${esc(x.narration)}</td><td>${moneyMinor(x.debitMinor)}</td><td>${moneyMinor(x.creditMinor)}</td><td>${moneyMinor(x.balanceMinor)}</td></tr>`)):empty("No ledger movement","No Posted lines match this account and date range.")}</section>`}
function direct(type){const income=type==="Income",a=state.accounts.filter(x=>x.companyId===companyId()&&x.type===(income?"Income":"Expense"));return head(type,income?"Record non-sales income with an accounting preview.":"Record direct or credit expenses without duplicating Purchase Bills.",`<button class="btn primary" data-action="${income?"income":"expense"}">Add ${income?"Income":"Expenses"}</button>`)+`<section class="panel">${a.length?table(["Code","Account","Posted balance","Ledger"],a.map(x=>{const b=ledger(state,{companyId:companyId(),accountId:x.id}).at(-1)?.balanceMinor||0;return`<tr><td>${x.code}</td><td>${esc(x.name)}</td><td>${moneyMinor(b)}</td><td><button class="text-button" data-ledger="${x.id}">Open</button></td></tr>`})):empty(`No ${type.toLowerCase()} accounts`,`Create or confirm the Chart of Accounts first.`)}</section>`}
function subledger(type){const sales=type==="Receivables",ctrl=state.accounts.find(x=>x.companyId===companyId()&&x.controlType===(sales?"Accounts Receivable":"Accounts Payable")),r=ctrl?ledger(state,{companyId:companyId(),accountId:ctrl.id,start:filters.start,end:filters.end}):[],groups=new Map;for(const x of state.journals.filter(x=>x.companyId===companyId()&&x.status==="Posted"))for(const l of x.lines.filter(l=>l.accountId===ctrl?.id)){const k=l.subledgerId||"Unallocated",g=groups.get(k)||{debit:0,credit:0};g.debit+=l.debitMinor;g.credit+=l.creditMinor;groups.set(k,g)}return head(type,`Control-account reconciliation and ${sales?"customer":"supplier"} sub-ledgers.`)+`<section class="metrics"><article class="metric"><span>Control balance</span><strong>${ctrl?moneyMinor(r.at(-1)?.balanceMinor||0):"Data not available"}</strong></article><article class="metric"><span>Sub-ledger references</span><strong>${groups.size}</strong></article><article class="metric"><span>Unallocated</span><strong>${moneyMinor((groups.get("Unallocated")?.debit||0)-(groups.get("Unallocated")?.credit||0))}</strong></article></section><section class="panel">${groups.size?table([sales?"Customer":"Supplier","Debit","Credit","Net"],[...groups].map(([k,v])=>`<tr><td>${esc(k)}</td><td>${moneyMinor(v.debit)}</td><td>${moneyMinor(v.credit)}</td><td>${moneyMinor(sales?v.debit-v.credit:v.credit-v.debit)}</td></tr>`)):empty("No sub-ledger postings","Post connected invoices, bills or payments to populate this view.")}</section>`}
function costCentres(){const a=state.costCentres.filter(x=>x.companyId===companyId());return head("Cost Centres","Branch, department, project, channel, marketplace and warehouse dimensions.",`<button class="btn primary" data-action="cost-centre">Add cost centre</button>`)+`<section class="panel">${a.length?table(["Code","Name","Type","Branch","Parent","Status"],a.map(x=>`<tr><td>${x.code}</td><td>${esc(x.name)}</td><td>${x.type}</td><td>${esc(x.branchId||"All")}</td><td>${esc(x.parentId||"—")}</td><td>${badge(x.active?"Active":"Inactive")}</td></tr>`)):empty("No cost centres","Add a cost centre when dimensional reporting is required.")}</section>`}
