function loans(){const a=state.loans.filter(x=>x.companyId===companyId());return head("Loans & Advances","Principal and interest remain separately accountable.",`<button class="btn primary" data-action="loan">Add loan / advance</button> <button class="btn secondary" data-action="loan-received">Record loan received</button> <button class="btn secondary" data-action="loan-repayment">Record loan repayment</button> <button class="btn secondary" data-action="owner-capital">Record owner capital</button> <button class="btn secondary" data-action="owner-drawings">Record owner drawings</button>`)+`<section class="panel">${a.length?table(["Type","Party","Principal","Interest rate","Start","Outstanding","Status"],a.map(x=>`<tr><td>${x.type}</td><td>${esc(x.party)}</td><td>${moneyMinor(x.principalMinor)}</td><td>${x.interestRate}%</td><td>${x.startDate}</td><td>${moneyMinor(x.outstandingPrincipalMinor)}</td><td>${badge(x.status)}</td></tr>`)):empty("No loans or advances","Principal repayments will not be treated as expenses.")}</section>`}
function gstLedgers(){const ae=globalThis.InfoBridgeCountryConfig?.country==="AE",system=ae?"VAT":"GST",names=ae?["Input VAT","Output VAT","VAT Payable"]:["Input CGST","Input SGST","Input IGST","Output CGST","Output SGST","Output IGST","GST Payable"],a=state.accounts.filter(x=>x.companyId===companyId()&&names.includes(x.name));return head(`${system} Ledgers`,ae?"Finance ledger view for internal UAE VAT reporting preparation.":"Finance ledger view; filing and JSON remain in GST Workspace.",ae?"":`<a class="btn secondary" href="/app/gst/index.html">Open GST Workspace</a>`)+`<section class="panel">${a.length?table(["Ledger","Balance","Finance source",`${system} comparison`],a.map(x=>`<tr><td>${x.name}</td><td>${moneyMinor(ledger(state,{companyId:companyId(),accountId:x.id}).at(-1)?.balanceMinor||0)}</td><td>Posted journals</td><td>${badge(ae?"Review in VAT report":"Review in GST Workspace")}</td></tr>`)):empty(`${system} accounts unavailable`, `Confirm the default chart and ${system} mappings.`)}</section>`}
function tb(){const x=trialBalance(state,{companyId:companyId(),start:filters.start,end:filters.end});return head("Trial Balance","Posted journals only; any difference is displayed prominently.",`<button class="btn secondary" data-export="trial">Export Excel</button>`)+`<section class="metrics"><article class="metric"><span>Total Closing Debit</span><strong>${moneyMinor(x.debit)}</strong></article><article class="metric"><span>Total Closing Credit</span><strong>${moneyMinor(x.credit)}</strong></article><article class="metric ${x.balanced?"":"danger"}"><span>Difference</span><strong>${moneyMinor(x.difference)}</strong></article><article class="metric"><span>Status</span><strong>${x.balanced?"Balanced":"UNBALANCED"}</strong></article></section><section class="panel">${table(["Code","Account","Opening Dr","Opening Cr","Period Dr","Period Cr","Closing Dr","Closing Cr"],x.rows.map(r=>`<tr><td>${r.code}</td><td><button class="text-button" data-ledger="${r.accountId}">${esc(r.name)}</button></td>${["openingDebit","openingCredit","periodDebit","periodCredit","closingDebit","closingCredit"].map(k=>`<td>${moneyMinor(r[k])}</td>`).join("")}</tr>`))}</section>`}
function statement(type){const x=statements(state,{companyId:companyId(),start:filters.start,end:filters.end});if(type==="Profit & Loss")return head(type,"Posted income and expense accounts; COGS remains incomplete when source cost is unavailable.")+`<section class="panel padded"><div class="statement-row"><span>Total Income</span><strong>${moneyMinor(x.profitLoss.income)}</strong></div><div class="statement-row"><span>Total Expenses</span><strong>${moneyMinor(x.profitLoss.expenses)}</strong></div><div class="statement-row statement-total"><span>Net Profit / (Loss)</span><strong>${moneyMinor(x.profitLoss.netProfit)}</strong></div><p class="form-note">GST control balances are excluded. This is final only to the extent all operational sources and COGS have been posted.</p></section>`;return head(type,"Accounting equation from Posted journal balances.")+`<section class="metrics"><article class="metric"><span>Assets</span><strong>${moneyMinor(x.balanceSheet.assets)}</strong></article><article class="metric"><span>Liabilities</span><strong>${moneyMinor(x.balanceSheet.liabilities)}</strong></article><article class="metric"><span>Equity incl. current profit</span><strong>${moneyMinor(x.balanceSheet.equity)}</strong></article><article class="metric ${x.balanceSheet.balanced?"":"danger"}"><span>Difference</span><strong>${moneyMinor(x.balanceSheet.difference)}</strong></article></section><p class="form-note">${x.balanceSheet.balanced?"Assets equal Liabilities plus Equity.":"UNBALANCED: this statement must not be treated as final."}</p>`}
function cashFlow(){const cashAccounts=state.accounts.filter(x=>x.companyId===companyId()&&["Cash","Bank"].includes(x.controlType)),r=cashAccounts.flatMap(a=>ledger(state,{companyId:companyId(),accountId:a.id,start:filters.start,end:filters.end})),classify=x=>/asset|loan|capital|drawings/i.test(x.narration)?(/loan|capital|drawings/i.test(x.narration)?"Financing":"Investing"):"Operating",groups={Operating:0,Investing:0,Financing:0};r.forEach(x=>groups[classify(x)]+=x.debitMinor-x.creditMinor);const net=Object.values(groups).reduce((a,n)=>a+n,0);return head("Cash Flow","Posted cash/bank lines classified using configurable narration mappings.")+`<section class="panel padded">${Object.entries(groups).map(([k,v])=>`<div class="statement-row"><span>Net Cash from ${k} Activities</span><strong>${moneyMinor(v)}</strong></div>`).join("")}<div class="statement-row statement-total"><span>Net Change in Cash</span><strong>${moneyMinor(net)}</strong></div><p class="form-note">Classification mappings can be refined in Settings; closing cash is reconciled through cash and bank control accounts.</p></section>`}
