// Central Confirm & Post: posts the Finance journal first (existing sourceLinks dedup), and
// only then -- if the journal actually represents real money moving (cashLink present) --
// creates exactly one linked Banking transaction. A journal with no cashLink (an invoice,
// bill, or non-cash adjustment) never touches Banking here, by construction.
// "Confirm & Post" is a dedicated Administration/Roles & Permissions action (see
// src/administration/core.js ACTIONS) editable from Company Member Access, exactly like every
// other module action. The Owner always has full access, matching every other permission check
// in this app (src/auth/module-access.js, src/approvals/app.js). This is enforced inside
// postJournalAndSync/reverseJournalAndSync themselves -- the single choke point every posting
// and reversal action in this page already funnels through -- so it cannot be bypassed by
// skipping a button (devtools, a scripted click, a stale cached view): the mutation itself
// refuses to run without the permission, not just the control that triggers it.
function reviewerName(){const u=globalThis.InfoBridgeUser||{};return u.user_metadata?.full_name||u.user_metadata?.name||u.email||"Finance"}
function canPostFinance(){
  const co=globalThis.InfoBridgeCompany||{},user=globalThis.InfoBridgeUser||{};
  if(co.ownerId&&user.id&&co.ownerId===user.id)return true;
  if(String(co.accessRole||"").toLowerCase()==="owner")return true;
  return Boolean(co.accessPermissions?.["Finance & Accounting"]?.["Confirm & Post"]);
}
function postJournalAndSync(startState,journalId,{accountId}={}){
  if(!canPostFinance())throw Error("You do not have permission to Confirm & Post Finance transactions. Ask an Owner or Administrator to grant Finance & Accounting → Confirm & Post.");
  let posted=postJournal(startState,journalId);
  const journal=posted.record;
  if(journal.cashLink&&!journal.cashLink.bankingTransactionId){
    const bankResult=syncFinancePosting(bankingRepository.load(),journal,{accountId});
    bankingRepository.save(bankResult.state);
    if(bankResult.record&&!bankResult.duplicate)posted=attachBankingTransaction(posted.state,journal.id,bankResult.record.id);
  }
  if(journal.source)writeSourceReviewStatus(journal.source,"Posted",{reviewer:reviewerName()});
  return posted;
}
// Central reversal: reverses the Finance journal, and if it had a linked Banking transaction,
// reverses that SAME transaction in place (never a second offsetting one) so the balance is
// restored exactly once. Posted history (the original journal, the original transaction) is
// never deleted -- only status-flipped, per the reversal requirement.
function reverseJournalAndSync(startState,journalId,date,reason){
  if(!canPostFinance())throw Error("You do not have permission to reverse a Posted Finance transaction. Ask an Owner or Administrator to grant Finance & Accounting → Confirm & Post.");
  const original=startState.journals.find(j=>j.id===journalId);
  const reversed=reverseJournal(startState,journalId,date,reason);
  if(original?.cashLink?.bankingTransactionId){
    const bankResult=reverseFinancePosting(bankingRepository.load(),original,reason);
    if(bankResult.record&&!bankResult.duplicate)bankingRepository.save(bankResult.state);
  }
  return reversed;
}
